    const ctx = canvas.getContext("2d")!;
    ctx.font = '32px "Mesh Talk Country Flags"';
    return ["🇯🇵", "🇺🇦"].map((flag) => {
      const [first, second] = [...flag];
      return ctx.measureText(flag).width < ctx.measureText(first).width + ctx.measureText(second).width;
